use ana_blockchain::{create_wallet,open_wallet,sign,address,Transaction};
use anyhow::{bail,Result};use serde::Serialize;use std::{env,net::TcpStream,io::Write,path::Path};
#[derive(Serialize)]struct Message{kind:String,transaction:Option<Transaction>}
fn main()->Result<()>{let a:Vec<String>=env::args().collect();match a.get(1).map(String::as_str){Some("new")=>{let p=a.get(2).map(String::as_str).unwrap_or("ana-wallet.json");println!("New ANA address: {}",create_wallet(Path::new(p))?);println!("Keep the wallet file private and backed up.");},Some("address")=>{let p=a.get(2).map(String::as_str).unwrap_or("ana-wallet.json");println!("{}",address(&open_wallet(Path::new(p))?.verifying_key()));},Some("send")=>{if a.len()!=7{bail!("Usage: ana-wallet send <wallet-file> <recipient> <amount-ANA> <fee-ANA> <node-ip:port>")}let k=open_wallet(Path::new(&a[2]))?;let amount=(a[4].parse::<f64>()?*100_000_000.0).round()as u64;let fee=(a[5].parse::<f64>()?*100_000_000.0).round()as u64;let tx=sign(&k,a[3].clone(),amount,fee,0)?;let wire=serde_json::to_string(&Message{kind:"transaction".into(),transaction:Some(tx)})?+"\n";TcpStream::connect(&a[6])?.write_all(wire.as_bytes())?;println!("Signed transaction submitted to {}",a[6]);},_=>println!("ANA wallet alpha: new [file] | address [file] | send <file> <recipient> <amount> <fee> <node>")}Ok(())}